/**
 * The demo journal's trades: invented, but on real prices.
 *
 * A showcase of made-up numbers falls apart at the first chart: an entry at
 * a price the market never printed. So the sample trades are generated by
 * walking real hourly candles. An entry is a bar's close; the stop is a
 * multiple of the range the market was moving in; the plan is then played
 * forward bar by bar to see what it would have done, and a trader with
 * recognisable habits is laid over it — taking some winners early, moving
 * a stop to breakeven, sizing up after a loss now and then. Best reach and
 * worst dip are the candles' own. Every figure the journal derives from a
 * trade is therefore one it could have derived from a real one.
 *
 * Pure, and seeded: the same candles and the same seed give the same
 * journal, which is what lets it be tested.
 */
import type { ScreenerCandle } from "./screener";

const HOUR = 3600_000;

/** A small seeded generator (mulberry32): the demo must not change between two visits a minute apart. */
export function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface DemoTrade {
  symbol: string;
  direction: "long" | "short";
  size: number;
  entryPrice: number;
  initialStop: number;
  initialTarget: number;
  entryTime: string;
  exitPrice: number | null;
  exitTime: string | null;
  status: "open" | "closed";
  mfe: number | null;
  mae: number | null;
  exitReason: "target" | "stop" | "breakeven" | "discretion" | "time" | null;
  noManagementOutcome: "target_first" | "stop_first" | "undetermined" | null;
  entryType: "limit" | "market";
  fees: number;
  riskAmount: number;
  notes: string | null;
  /** Gone over, for all but the last few days: a journal with a backlog of a hundred is not a kept one. */
  reviewedAt: string | null;
  wellTraded: boolean;
  tradedPoorly: boolean;
  tilt: boolean;
  /** A habit the trade shows, for a mistake tag: null when it was clean. */
  mistake: "early-exit" | "oversized" | "chased" | null;
}

const NOTES = {
  target: ["Plan played out. Entered on the retest, left it alone.", "Clean one: level held, target hit without touching it.", "Waited for the close back above the level before entering. Patience paid.", "Took the setup from the morning plan. No changes after entry."],
  stop: ["Stopped. The level gave way quickly; nothing to manage.", "Wrong on direction. Took the loss at the stop, as planned.", "Stop hit. Entry was fine, the market just did not agree.", "Lost 1R. Would take this setup again."],
  early: ["Took it off early because it stalled under the high. It went on to the target without me.", "Closed by hand at +1R. Nervous after the last loss. Target hit an hour later.", "Got out early again. Need to let the plan work."],
  breakeven: ["Moved the stop to entry once it was +1R up. Tagged out flat before the move continued.", "Breakeven stop took me out. Too tight too soon."],
  time: ["Nothing happened. Closed it before the weekend.", "Went sideways for two days. Closed flat-ish and moved on."],
  tilt: ["Revenge trade. Took it minutes after the stop-out, double size. Not in the plan.", "Sized up to win the last loss back. This is the pattern to stop."],
  chased: ["Chased the breakout with a market order. Entry was late and the stop too wide for it.", "Bought the candle instead of waiting for the pullback."],
};
const pick = <T,>(r: () => number, xs: readonly T[]): T => xs[Math.floor(r() * xs.length)];

/** The average hourly range over the 14 bars before `i`, as a price distance. */
function range14(c: ScreenerCandle[], i: number): number {
  let s = 0;
  for (let k = i - 13; k <= i; k++) s += c[k].h - c[k].l;
  return s / 14;
}

/**
 * Sample trades over the candles given. `count` closed trades spread over
 * the series, then one open trade per two symbols in the last day. A symbol
 * with under ten days of bars is left out.
 */
export function demoTrades(series: Map<string, ScreenerCandle[]>, opts: { seed?: number; count?: number; risk?: number } = {}): DemoTrade[] {
  const r = rng(opts.seed ?? 20260101);
  const count = opts.count ?? 110;
  const baseRisk = opts.risk ?? 100;
  const symbols = Array.from(series.entries()).filter(([, c]) => c.length >= 240);
  if (symbols.length === 0) return [];
  const out: DemoTrade[] = [];
  let lastLossAt = -Infinity;

  const make = (symbol: string, c: ScreenerCandle[], i: number, open: boolean): DemoTrade | null => {
    const entry = c[i].c;
    const rangeNow = range14(c, i);
    if (!(entry > 0) || !(rangeNow > 0)) return null;
    /*
     * A sample trader has to be worth looking at: one with an edge and with
     * habits that cost some of it. The edge is given, not found — three
     * times in five the side is the one the next day and a half went to,
     * the rest a coin toss with the day's drift. It is sample data and says
     * so; what matters is that every figure on it is the journal's own.
     */
    const ahead = c[Math.min(c.length - 1, i + 36)].c - c[i].c;
    const drift = c[i].c - c[i - 24].c;
    const long = !open && r() < 0.6 ? ahead >= 0 : r() < 0.5 ? drift >= 0 : drift < 0;
    const sign = long ? 1 : -1;
    const dist = rangeNow * (1.6 + r() * 1.6);
    const rr = pick(r, [1.5, 2, 2, 3]);
    const stop = entry - sign * dist;
    const target = entry + sign * dist * rr;
    const entryAt = c[i].t + HOUR;
    const tilt = !open && entryAt - lastLossAt < 3 * HOUR && r() < 0.25;
    const chased = !tilt && r() < 0.08;
    const riskAmount = baseRisk * (tilt ? 2 : 0.8 + r() * 0.4);
    const size = riskAmount / dist;
    const entryType: "limit" | "market" = tilt || chased ? "market" : r() < 0.6 ? "limit" : "market";
    const base = { symbol, direction: long ? ("long" as const) : ("short" as const), size: Number(size.toPrecision(5)), entryPrice: entry, initialStop: Number(stop.toPrecision(7)), initialTarget: Number(target.toPrecision(7)), entryTime: new Date(entryAt).toISOString(), entryType, riskAmount: Number(riskAmount.toFixed(2)), tilt };
    if (open) return { ...base, exitPrice: null, exitTime: null, status: "open", mfe: null, mae: null, exitReason: null, noManagementOutcome: null, fees: 0, notes: "Still on. Stop where the idea is wrong; no reason to touch it yet.", reviewedAt: null, wellTraded: false, tradedPoorly: false, mistake: null };

    // The plan, left alone: which of the stop and the target the candles reach first, within three days.
    const habit = r();
    let plan: "target_first" | "stop_first" | "undetermined" = "undetermined";
    let exit: { price: number; at: number; reason: DemoTrade["exitReason"] } | null = null;
    let best = entry;
    let worst = entry;
    let beStop = false;
    // In the trade for three days at most; the plan is followed for ten, so what it would have done is known.
    const last = Math.min(c.length - 1, i + 72);
    for (let k = i + 1; k <= Math.min(c.length - 1, i + 240); k++) {
      const bar = c[k];
      const hi = long ? bar.h : bar.l;
      const lo = long ? bar.l : bar.h;
      const hitStop = sign * (lo - stop) <= 0;
      const hitTarget = sign * (hi - target) >= 0;
      if (plan === "undetermined") plan = hitStop ? "stop_first" : hitTarget ? "target_first" : "undetermined";
      if (!exit && k > last) exit = { price: c[last].c, at: c[last].t + HOUR, reason: "time" };
      if (exit) {
        if (plan !== "undetermined") break;
        continue;
      }
      // The extremes while in the trade, the worst side first within a bar.
      if (sign * (lo - worst) < 0) worst = lo;
      if (hitStop) {
        exit = { price: stop, at: bar.t + HOUR, reason: "stop" };
        continue;
      }
      if (beStop && sign * (lo - entry) <= 0) {
        exit = { price: entry, at: bar.t + HOUR, reason: "breakeven" };
        continue;
      }
      if (sign * (hi - best) > 0) best = hi;
      if (hitTarget) {
        exit = { price: target, at: bar.t + HOUR, reason: "target" };
        continue;
      }
      const upR = (sign * (hi - entry)) / dist;
      // The habits: a quarter of the time, out by hand a little past +1R; one in eight, the stop to entry at +1R.
      // Never at a price the bar did not reach: somewhere between +1R and the bar's own extreme.
      if (habit < 0.25 && upR >= 1.1) exit = { price: entry + sign * dist * (1 + r() * Math.min(0.2, upR - 1)), at: bar.t + HOUR, reason: "discretion" };
      else if (habit >= 0.25 && habit < 0.37 && upR >= 1) beStop = true;
    }
    if (!exit) exit = { price: c[last].c, at: c[last].t + HOUR, reason: "time" };
    const won = sign * (exit.price - entry) > 0;
    if (!won && exit.reason === "stop") lastLossAt = exit.at;
    const early = exit.reason === "discretion" && plan === "target_first";
    const notes = tilt ? pick(r, NOTES.tilt) : chased ? pick(r, NOTES.chased) : early ? pick(r, NOTES.early) : exit.reason === "breakeven" ? pick(r, NOTES.breakeven) : exit.reason === "time" ? pick(r, NOTES.time) : exit.reason === "target" ? pick(r, NOTES.target) : exit.reason === "stop" ? pick(r, NOTES.stop) : null;
    return {
      ...base,
      exitPrice: Number(exit.price.toPrecision(7)),
      exitTime: new Date(exit.at).toISOString(),
      status: "closed",
      mfe: best,
      mae: worst,
      exitReason: exit.reason,
      noManagementOutcome: plan,
      fees: Number((size * entry * 0.0009).toFixed(2)),
      // Two notes in three: a journal with a note on every trade is nobody's.
      notes: r() < 0.67 || tilt ? notes : null,
      reviewedAt: c[c.length - 1].t - exit.at > 3 * 24 * HOUR ? new Date(exit.at + 6 * HOUR).toISOString() : null,
      wellTraded: !tilt && !chased && (exit.reason === "target" || (exit.reason === "stop" && r() < 0.5)),
      tradedPoorly: tilt || chased || early,
      mistake: tilt ? "oversized" : chased ? "chased" : early ? "early-exit" : null,
    };
  };

  // In time order, so "minutes after a loss" means something.
  const picks: { symbol: string; c: ScreenerCandle[]; i: number }[] = [];
  for (let n = 0; n < count; n++) {
    const [symbol, c] = pick(r, symbols);
    picks.push({ symbol, c, i: 30 + Math.floor(r() * (c.length - 30 - 80)) });
  }
  picks.sort((a, b) => a.c[a.i].t - b.c[b.i].t);
  for (const p of picks) {
    const t = make(p.symbol, p.c, p.i, false);
    if (t) out.push(t);
  }
  symbols.slice(0, Math.max(1, Math.ceil(symbols.length / 2))).forEach(([symbol, c]) => {
    const t = make(symbol, c, c.length - 2 - Math.floor(r() * 12), true);
    if (t) out.push(t);
  });
  return out;
}

/** Hourly candles to stand in when the venue cannot be asked: a random walk from a starting price, so the demo is never empty. */
export function syntheticCandles(start: number, bars: number, endAt: number, seed: number): ScreenerCandle[] {
  const r = rng(seed);
  const out: ScreenerCandle[] = [];
  let px = start;
  const t0 = Math.floor(endAt / HOUR) * HOUR - bars * HOUR;
  for (let i = 0; i < bars; i++) {
    const o = px;
    const c = o * (1 + (r() - 0.49) * 0.012);
    const h = Math.max(o, c) * (1 + r() * 0.004);
    const l = Math.min(o, c) * (1 - r() * 0.004);
    out.push({ t: t0 + i * HOUR, o, h, l, c, v: 1000 + r() * 500 });
    px = c;
  }
  return out;
}
